import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Readable } from 'node:stream';
import { transformarChunks } from './solution.mjs';

test('transforma os pedaços de uma stream de verdade (Readable)', async () => {
  const resultado = await transformarChunks(
    Readable.from(['olá ', 'mundo']),
    (pedaco) => pedaco.toString().toUpperCase()
  );
  assert.equal(resultado, 'OLÁ MUNDO');
});

test('transforma os pedaços de uma lista comum (for await funciona nas duas)', async () => {
  const resultado = await transformarChunks(['a', 'b', 'c'], (pedaco) => pedaco + '!');
  assert.equal(resultado, 'a!b!c!');
});

test('fonte vazia devolve string vazia', async () => {
  assert.equal(await transformarChunks([], (pedaco) => pedaco), '');
});

test('lança erro em entradas inválidas', async () => {
  await assert.rejects(() => transformarChunks(['a'], 'não é função'), /função/);
  await assert.rejects(() => transformarChunks(null, (pedaco) => pedaco), /pedaços/);
});

solutionCode:
export async function transformarChunks(chunks, funcao) {
  if (chunks === null || chunks === undefined) {
    throw new Error('chunks precisa ser uma fonte de pedaços');
  }
  if (typeof funcao !== 'function') {
    throw new Error('funcao precisa ser uma função');
  }

  let resultado = '';
  for await (const pedaco of chunks) {
    resultado += funcao(pedaco);
  }
  return resultado;
}
